 function fairBuy(key,id){let shop=currentShop(key),row=shop?.stock?.find(entry=>entry.itemId===id),d=typeof itemDef==='function'?itemDef(id):null;if(!row||row.qty<1||licensedShop(d)!==key)return typeof toast==='function'?toast('That item is not on this shop’s shelf.'):false;let input=document.getElementById?.('v70q_'+id),qty=Math.floor(bounded(parseInt(input?.value||1),1,row.qty)),cost=shopRowCopper(row,d,S.world.location)*qty,dest=destination();if(typeof moneyCopper==='function'&&moneyCopper()<cost)return toast('Insufficient physical coin.');if(!dest||!S.containers?.[dest])return toast('Choose an accessible container for this purchase.');let stack=typeof mkStack==='function'?mkStack(id,qty,row.condition):{itemId:id,qty,condition:row.condition};if(typeof canAdd==='function'&&!canAdd(S.containers[dest],stack))return toast('The selected container cannot hold this purchase.');if(typeof payCopper==='function'&&!payCopper(cost))return toast('Insufficient accessible physical coin.');let added=typeof addItem==='function'?addItem(dest,id,qty,row.condition,{acquiredAt:`${typeof V51_MERCHANTS!=='undefined'&&V51_MERCHANTS[key]?.name||'Shop'}, ${S.world.location}`}):false;if(!added){if(typeof earnCopper==='function')earnCopper(cost);return toast('The purchase could not be packed; your coin was returned.')}row.qty-=qty;shop.cashCopper=(+shop.cashCopper||0)+cost;S.v70.shopHistory??=[];S.v70.shopHistory.push({day:S.world.day,action:'buy',key,id,qty,cost,dest,location:S.world.location});S.v70.shopHistory=S.v70.shopHistory.slice(-200);if(typeof persist==='function')persist(false);if(typeof render==='function')render();return true}
